**Instalação do Node.js e o Mongoose**

### Passo 1: Instalar Node.js e Mongoose

```bash
# Instale Node.js e Mongoose
npm init -y
npm install mongoose
```

### Passo 2: Configurar o Mongoose

```javascript
// Criar um arquivo `mongoose.js` no diretório raiz do projeto
// e adicione o seguinte conteúdo:
const mongoose = require('mongoose');

mongoose.connect('mongodb://localhost:27017/mydatabase', { useNewUrlParser: true, useUnifiedTopology: true });
```

### Passo 3: Criar um Banco de Dados

```javascript
// Criar um arquivo `schema.js` no diretório raiz do projeto
// e adicione o seguinte conteúdo:
const mongoose = require('mongoose');

const dbConfig = {
  uri: 'mongodb://localhost:27017/mydatabase',
  useNewUrlParser: true,
  useUnifiedTopology: true
};

module.exports = mongoose.createDatabase(dbConfig);
```

### Passo 4: Criar um Modelo

```javascript
// Criar um arquivo `models/user.js` no diretório raiz do projeto
// e adicione o seguinte conteúdo:
const mongoose = require('mongoose');

const userSchema = new mongoose.Schema({
  nome: String,
  email: String,
  senha: String
});

const User = mongoose.model('User', userSchema);
```

### Passo 5: Criar um Usuário

```javascript
// Criar um arquivo `controllers/userController.js` no diretório raiz do projeto
// e adicione o seguinte conteúdo:
const User = require('../models/user');

exports.create = async (req, res) => {
  try {
    const user = new User(req.body);
    await user.save();
    res.status(201).json(user);
  } catch (err) {
    res.status(400).json(err);
  }
};
```

### Passo 6: Iniciar o Serviço

```javascript
// Criar um arquivo `app.js` no diretório raiz do projeto
// e adicione o seguinte conteúdo:
const express = require('express');
const app = express();
const userController = require('./controllers/userController');

app.use(express.json());
app.use('/users', userController);

app.listen(3000, () => {
  console.log('Serviço iniciado no port 3000');
});
```

### Exemplo de uso

```bash
curl -X POST http://localhost:3000/users -H "Content-Type: application/json" -d '{"nome": "John Doe", "email": "johndoe@example.com", "senha": "123456"}'
```

